      "eighty.text": "कम आय वर्ग के लोग दुनिया भर में नागरिक मामलों के लिए कानूनी प्रतिनिधित्व का खर्च नहीं उठा सकते, जो कानूनी सहायता की किफायत की व्यापक समस्या को उजागर करता है।",
      "ninetytwo.text": "Lawify 92% और उससे अधिक की शानदार सटीकता के साथ काम करता है।",
      "howitworks.eyebrow": "Lawify कैसे काम करता है?",
      "howitworks.text": "Lawify एक अत्यधिक प्रशिक्षित एलएलएम का उपयोग करता है, जिसे हाइपर-ट्यूनिंग के माध्यम से विशेष रूप से कानूनी प्रश्नों के लिए अनुकूलित किया गया है। उपयोगकर्ता अपने वांछित क्षेत्र का चयन करते हैं, जिससे उस क्षेत्र के कानूनी ढांचे पर आधारित एक अनुकूलित चैट सत्र शुरू होता है। इसके बाद Lawify संबंधित कानूनी दस्तावेज़, जिनमें संविधान, आचार संहिता, कानून और हाल के संशोधन शामिल हैं, लोड करता है।<br><br>हमारा प्लेटफ़ॉर्म वैधानिक कानूनों, न्यायिक उदाहरणों, नियामक दिशानिर्देशों और अन्य कानूनी दस्तावेज़ों के व्यापक डेटाबेस को एकीकृत करता है। इससे सुनिश्चित होता है कि मॉडल के पास सटीक और प्रासंगिक उत्तरों के लिए एक विशाल भंडार है। Lawify की ताकत इसके क्षेत्र-विशिष्ट प्रशिक्षण में है, जिसमें स्थानीय कानूनी शब्दावली, प्रक्रियाओं और संदर्भगत बारीकियों से व्यापक परिचय शामिल है, जो सटीक और प्रासंगिक उत्तर सुनिश्चित करता है।<br><br>",
      "funding.eyebrow": "फंडिंग",
      "funding.heading": "दुनिया के सर्वश्रेष्ठ संस्थानों द्वारा समर्थित",
      "funding.text": "हमें संयुक्त राष्ट्र के कार्यकारी प्रभाग के सदस्यों से मार्गदर्शन मिला और Harvard MUN Impact Initiative से फंडिंग प्राप्त हुई - जिसमें हमें 400 USD का तीसरा समग्र पुरस्कार मिला। हम आगे और फंडिंग के लिए Diana, Duke of Edinburgh जैसे प्रतिष्ठित पुरस्कारों के लिए आवेदन करने की भी योजना बना रहे हैं। यह फंडिंग आवश्यक है क्योंकि मॉडल को GPT4o टोकन की आवश्यकता होती है, जिसकी लागत लगभग 20 USD प्रति 10 लाख टोकन है। हमारी World Foundation for Peace and Sustainability के साथ भी संभावित साझेदारी है ताकि हमारे प्लेटफ़ॉर्म को बढ़ावा मिल सके।",
