      "member.vatsal.bio": "व्यावसायिक उपक्रमों में अत्यंत कुशल, चाहे वह विज्ञापन हो, मार्केटिंग हो या लॉजिस्टिक्स, उन्हें किसी संगठन को चलाने से जुड़े सभी क्षेत्रों का व्यापक ज्ञान है।",
      "role.outreach": "आउटरीच प्रमुख",
      "member.sai.bio": "आर्टिफिशियल इंटेलिजेंस और वेबसाइट निर्माण में महत्वपूर्ण ज्ञान रखने वाले एक टेक्नोलॉजी और सीएस विशेषज्ञ। उन्होंने कोडिंग के कौशल में महारत हासिल की है।",
      "role.techhead": "टेक प्रमुख",
      "team.heading2": "हमारी मुख्य टीम",
      "member.nimay.bio": "विज्ञापन, मार्केटिंग या सोशल मीडिया उपस्थिति में, वे रचनात्मकता, प्रचार और समग्र प्रमोशन के मामले में सही मायने में एक पेशेवर हैं।",
      "role.marketing": "मार्केटिंग प्रमुख",
