      "member.nimay.bio": "বিজ্ঞাপন, মার্কেটিং বা সোশ্যাল মিডিয়া উপস্থিতি, সৃজনশীলতা, প্রচার বা সামগ্রিক প্রসারের ক্ষেত্রে তিনি সত্যিই একজন পেশাদার।",
