      "voicechat.intro": "మీ చట్టపరమైన ప్రశ్నను బిగ్గరగా చెప్పండి, Lawify సమాధానాలను వినండి. మైక్‌లో మాట్లాడండి, టెక్స్ట్‌ను కింద ఉన్న చాట్‌లో కాపీ చేయండి, ఆ తర్వాత బాట్ సమాధానాన్ని రీడర్‌లో పేస్ట్ చేసి వినండి.",
