      "whatwedo.eyebrow": "आम्ही काय करतो",
      "whatwedo.heading": "कायदेशीर माहिती उपलब्ध नसल्याचे पाहून, कायद्याच्या माहितीच्या उपलब्धतेतील तफावत दूर करण्यासाठी पावले उचलण्याची आम्हाला प्रेरणा मिळाली - ही अशी समस्या आहे जी समाजांना खरोखर प्रभावित करते.",
