      "effective.title": "موثر استعمال",
      "effective.text": "اسے صارف کے ملک کے دائرہ اختیار کے بارے میں معلومات فراہم کرنے کے لیے بنایا گیا ہے، چاہے وہ قانونی مشورہ ہو، سابقہ مقدمات کی نظیریں تلاش کرنا ہو، یا ایکٹس اور کیس لاز کی تحقیق ہو۔<br><br>سوال جتنا درست اور تفصیلی ہوگا، Lawify صارفین کی ضروریات کے مطابق اتنا ہی بہتر جواب دے سکے گا۔ عمومی سوالات کا عمومی مشورہ ملے گا، جو الٹا نقصان دہ ہو سکتا ہے۔ Lawify صرف دستیاب آپشنز بیان کرے گا، نہ صارفین کی رہنمائی کرے گا اور نہ انہیں کوئی ایک چننے کو کہے گا۔ اسے عدالت کے اندر استعمال کرنے کے لیے نہیں بنایا گیا۔",
