      "howitworks.text": "Lawify ایک اچھی طرح تربیت یافتہ LLM استعمال کرتا ہے، جسے ہائپر ٹیوننگ کے ذریعے خاص طور پر قانونی سوالات کے لیے بہتر بنایا گیا ہے۔ صارفین اپنا مطلوبہ خطہ منتخب کرتے ہیں، جس سے اس خطے کے قانونی ڈھانچے کے مطابق ایک مخصوص چیٹ سیشن شروع ہو جاتا ہے۔ اس کے بعد Lawify منتخب خطے سے متعلق دستور، ضابطۂ اخلاق، قوانین اور حالیہ ترامیم سمیت متعلقہ قانونی دستاویزات لوڈ کرتا ہے۔<br><br>ہمارا پلیٹ فارم قانونی وسائل کے ایک جامع ڈیٹا بیس کو یکجا کرتا ہے، جیسے آئینی قوانین، عدالتی نظیریں، ریگولیٹری رہنما اصول اور دیگر قانونی متون۔ اس سے یہ یقینی ہوتا ہے کہ ماڈل کے پاس درست اور متعلقہ جوابات کے لیے وسیع ذخیرہ موجود ہو۔ Lawify کی طاقت اس کی خطے کے مطابق تربیت میں ہے، جس میں مقامی قانونی اصطلاحات، طریقۂ کار اور سیاق و سباق کی باریکیوں سے گہری واقفیت شامل ہے، اور یوں درست اور سیاق کے مطابق جوابات کی ضمانت ملتی ہے۔<br><br>",
