      "member.vatsal.bio": "کاروباری منصوبوں میں انتہائی ماہر، چاہے اشتہارات ہوں، مارکیٹنگ ہو یا لاجسٹکس؛ کسی ادارے کو چلانے سے متعلق تمام شعبوں میں وسیع علم رکھتے ہیں۔",
      "role.outreach": "سربراہ برائے رابطہ عامہ",
      "member.sai.bio": "ٹیکنالوجی اور کمپیوٹر سائنس کے ماہر جنہیں مصنوعی ذہانت اور ویب سائٹ بنانے میں نمایاں علم حاصل ہے۔ انہوں نے کوڈنگ کی مہارتوں پر عبور حاصل کر لیا ہے۔",
