      "voicechat.intro": "ਆਪਣਾ ਕਾਨੂੰਨੀ ਸਵਾਲ ਉੱਚੀ ਬੋਲੋ ਅਤੇ Lawify ਦੇ ਜਵਾਬ ਆਪਣੇ ਲਈ ਪੜ੍ਹਵਾਓ। ਮਾਈਕ ਵਿੱਚ ਬੋਲੋ, ਟੈਕਸਟ ਨੂੰ ਹੇਠਾਂ ਚੈਟ ਵਿੱਚ ਕਾਪੀ ਕਰੋ, ਫਿਰ ਬੋਟ ਦਾ ਜਵਾਬ ਰੀਡਰ ਵਿੱਚ ਪੇਸਟ ਕਰਕੇ ਸੁਣੋ।",
