      "hero.subtitle": "ਸਮਾਜਿਕ-ਆਰਥਿਕ ਪਿਛੋਕੜ ਦੀ ਪਰਵਾਹ ਕੀਤੇ ਬਿਨਾਂ, ਭਾਰਤ ਵਿੱਚ ਕਾਨੂੰਨੀ ਮਦਦ ਨੂੰ ਸਾਰਿਆਂ ਲਈ ਪਹੁੰਚਯੋਗ ਬਣਾਉਣ ਦਾ ਸਾਡਾ ਟੀਚਾ ਹੈ।",
