      "whatwedo.eyebrow": "ਅਸੀਂ ਕੀ ਕਰਦੇ ਹਾਂ",
      "whatwedo.heading": "ਕਾਨੂੰਨੀ ਜਾਣਕਾਰੀ ਦੀ ਪਹੁੰਚ ਦੀ ਘਾਟ ਨੂੰ ਦੇਖ ਕੇ, ਸਾਨੂੰ ਕਾਨੂੰਨੀ ਜਾਣਕਾਰੀ ਦੀ ਪਹੁੰਚ ਵਿੱਚ ਪਾੜੇ ਨੂੰ ਦੂਰ ਕਰਨ ਲਈ ਕਦਮ ਚੁੱਕਣ ਦੀ ਪ੍ਰੇਰਨਾ ਮਿਲੀ - ਇੱਕ ਅਜਿਹੀ ਸਮੱਸਿਆ ਜੋ ਸਮਾਜਾਂ ਨੂੰ ਸੱਚਮੁੱਚ ਪ੍ਰਭਾਵਿਤ ਕਰਦੀ ਹੈ।",
