      "audience.title": "আমাৰ দৰ্শক",
      "audience.text": "Lawify এ কোনো বিশেষ জনসংখ্যা শ্ৰেণীক লক্ষ্য নকৰে; বৰং, Lawify ত আমি বুজি পাওঁ যে বহু লোক বেলেগ বেলেগ আৰ্থ-সামাজিক পটভূমিৰ পৰা আহে আৰু সকলোৱে Lawify ব্যৱহাৰ কৰি উপকৃত হ'ব পাৰে। শোষিত শ্ৰমিক, নিৰ্যাতিত জীৱনসংগী, বা বিশ্বাসঘাতকতাৰ শিকাৰ সহ-প্ৰতিষ্ঠাপকৰ অসহনীয় কাহিনীবোৰৰ সমাধান এটা বুটাম টিপি আৰু বিনামূলীয়াকৈ কৰাটোৱেই আমাৰ লক্ষ্য।",
      "farmers.title": "কৃষকৰ বাবে",
      "farmers.text": "Lawify এ কৃষক আৰু গ্ৰাম্য সম্প্ৰদায়ৰ সৈতেও থিয় দিয়ে, মাটিৰ মালিকানাৰ কাগজ, ভাগচাষ আৰু উত্তৰাধিকাৰৰ নথি-পত্ৰ, আৰু চৰকাৰী পেঞ্চন আৰু কল্যাণমূলক আঁচনি সৰল ভাষাত বুজি পোৱাত সহায় কৰে — যাতে কাগজ-পত্ৰ বুজিবলৈ আৰু উকীল বা নগৰলৈ যাত্ৰাৰ প্ৰয়োজন নহয়।",
      "convenience.title": "সুবিধা আনি",
      "convenience.text": "Lawify ব্যৱহাৰ কৰাটো বিশ্বৰ যিকোনো ভাষাত ইনপুট বাকচত আপোনাৰ প্ৰশ্ন টাইপ কৰি এণ্টাৰ টিপাৰ দৰে সহজ (চেটবটটো অধিকাংশ আন্তৰ্জাতিক ভাষাত পাৰদৰ্শী)। প্ৰশ্নটো কিমান বিস্তৃত তাৰ ওপৰত নিৰ্ভৰ কৰি চেটবটে কেইসেকেণ্ডমানৰ ভিতৰতে উত্তৰ দিয়ে। Lawify এ ৰাজ্য, ধৰ্ম, বয়স আৰু লিংগৰ দৰে বিষয় বিবেচনা কৰে আৰু পৰৱৰ্তী প্ৰশ্নৰো উত্তৰ দিব পাৰে।",
      "whatyoushouldknow.eyebrow": "আপুনি যি জানিব লাগে",
      "whatyoushouldknow.heading": "Lawify মানুহৰ প্ৰয়োজনৰ পৰা জন্ম হৈছে।",
      "effective.title": "ফলপ্ৰসূ ব্যৱহাৰ",
      "effective.text": "ই ব্যৱহাৰকাৰীৰ দেশৰ এখতিয়াৰ সম্পৰ্কে তথ্য দিবলৈ ডিজাইন কৰা হৈছে, সেয়া আইনী পৰামৰ্শ হওক, গোচৰৰ নজিৰ বিচাৰ হওক, বা আইন আৰু গোচৰ-আইনৰ গৱেষণা হওক।<br><br>প্ৰম্পট যিমান সঠিক আৰু বিস্তৃত হয়, Lawify এ ব্যৱহাৰকাৰীৰ প্ৰয়োজন অনুসৰি নিজৰ উত্তৰ সিমানেই ভালকৈ সজাব পাৰে। সাধাৰণ প্ৰশ্ন সুধিলে সাধাৰণ পৰামৰ্শ পোৱা যাব, যিটো বিপৰীত ফলদায়ক হ'ব পাৰে। Lawify এ কেৱল উপলব্ধ বিকল্পবোৰৰ ৰূপৰেখা দিয়ে, ব্যৱহাৰকাৰীক পথ প্ৰদৰ্শন নকৰে বা এটা বাছি ল'বলৈ নকয়। ইয়াক আদালত কোঠাৰ ভিতৰত ব্যৱহাৰ কৰিবলৈ বনোৱা হোৱা নাই।",
      "quote.text": "“এই সমস্যাটো সঁচাকৈয়ে প্ৰকট আৰু ইয়াৰ সমাধান হ'ব লাগিব। অতি ভালদৰে প্ৰশিক্ষিত AI ৰ পৰা পোনপটীয়াকৈ সৃষ্টি হোৱা আইন সম্পৰ্কীয় তথ্য আটাইতকৈ ফলপ্ৰসূ আৰু দক্ষ ধৰণে যোগান ধৰাতকৈ উত্তম উপায় আৰু কি হ'ব পাৰে? এয়াই আটাইতকৈ ভাল সমাধান।”",
      "quote.author": "দল Lawify",
      "ratio.eyebrow": "আচৰিতভাৱে অনুপাতটো হৈছে",
      "ratio.text": "বিশ্বজুৰি গড়ে প্ৰতি 3,547 জন লোকৰ বাবে এজন উকীল আছে।",
      "eighty.text": "বিশ্বজুৰি নিম্ন-আয়ৰ ব্যক্তিসকলে দেৱানী গোচৰৰ বাবে আইনী প্ৰতিনিধিত্বৰ খৰচ বহন কৰিব নোৱাৰে, যিয়ে আইনী সহায়ৰ ব্যয়ভাৰ সম্পৰ্কীয় ব্যাপক সমস্যাটো উদ্ভাসিত কৰে।",
