      "howitworks.text": "Lawify এ আইনী প্ৰশ্নৰ বাবে হাইপাৰ-টিউনিঙৰ জৰিয়তে বিশেষভাৱে অনুকূলিত, উচ্চ প্ৰশিক্ষিত LLM ব্যৱহাৰ কৰে। ব্যৱহাৰকাৰীসকলে নিজৰ ইচ্ছাৰ অঞ্চল বাছনি কৰে, যিয়ে সেই অঞ্চলৰ আইনী কাঠামোৰ ওপৰত ভিত্তি কৰি এটা অনুকূলিত চেট ছেশ্বন আৰম্ভ কৰে। তাৰ পিছত Lawify এ বাছনি কৰা অঞ্চলৰ সৈতে জড়িত সংবিধান, আচৰণ বিধি, আইন আৰু শেহতীয়া সংশোধনীসমূহ আদি প্ৰাসংগিক আইনী নথি-পত্ৰ লোড কৰে।<br><br>আমাৰ প্লেটফৰ্মে বিধিবদ্ধ আইন, ন্যায়িক নজিৰ, নিয়ামক নিৰ্দেশিকা আৰু অন্যান্য আইনী লিখনিৰ দৰে আইনী সম্পদৰ এক ব্যাপক ডাটাবেছ অন্তৰ্ভুক্ত কৰে। ই মডেলটোক সঠিক আৰু প্ৰাসংগিক উত্তৰৰ বাবে এক বিশাল ভঁৰাল যোগান ধৰে। Lawify ৰ শক্তি ইয়াৰ অঞ্চল-নিৰ্দিষ্ট প্ৰশিক্ষণত নিহিত, য'ত স্থানীয় আইনী শব্দাৱলী, প্ৰক্ৰিয়া আৰু প্ৰাসংগিক সূক্ষ্মতাৰ সৈতে ব্যাপক পৰিচয় জড়িত, যিয়ে সঠিক আৰু প্ৰসংগ অনুকূল উত্তৰৰ নিশ্চয়তা দিয়ে।<br><br>",
      "funding.eyebrow": "অৰ্থ সাহায্য",
