      "funding.text": "আমি সংযুক্ত ৰাষ্ট্ৰসংঘৰ কাৰ্যনিৰ্বাহী বিভাগৰ সদস্যসকলৰ পৰা পথ প্ৰদৰ্শন লাভ কৰিলোঁ আৰু Harvard MUN Impact Initiative ৰ পৰা অৰ্থ সাহায্য লাভ কৰিলোঁ - যাত সামগ্ৰিকভাৱে তৃতীয় পুৰস্কাৰ 400 USD লাভ কৰিলোঁ। অধিক অৰ্থৰ বাবে আমি Diana, Duke of Edinburgh আদিৰ দৰে প্ৰখ্যাত বঁটাৰ বাবেও আবেদন কৰাৰ পৰিকল্পনা কৰিছোঁ। এই অৰ্থ অতি প্ৰয়োজনীয় কাৰণ মডেলটোৰ GPT4o টোকেন লাগে, যাৰ মূল্য 1 মিলিয়ন টোকেনৰ বাবে প্ৰায় 20 USD। আমাৰ প্লেটফৰ্মৰ প্ৰচাৰৰ বাবে World Foundation for Peace and Sustainability ৰ সৈতেও আমাৰ এক সম্ভাব্য অংশীদাৰিত্ব আছে।",
