      "howitworks.eyebrow": "Lawify कसरी काम गर्छ?",
      "howitworks.text": "Lawify ले कानुनी प्रश्नहरूका लागि हाइपर-ट्युनिङ मार्फत विशेष रूपमा अनुकूलित, उच्च प्रशिक्षित LLM प्रयोग गर्छ। प्रयोगकर्ताहरूले आफ्नो चाहेको क्षेत्र छान्छन्, जसले त्यस क्षेत्रको कानुनी ढाँचामा आधारित अनुकूलित च्याट सत्र सुरु गर्छ। त्यसपछि Lawify ले छानिएको क्षेत्रसँग सम्बन्धित संविधान, आचारसंहिता, कानुन र हालका संशोधनहरू लगायतका सान्दर्भिक कानुनी कागजातहरू लोड गर्छ।<br><br>हाम्रो प्लेटफर्मले वैधानिक कानुन, न्यायिक नजीर, नियामक निर्देशिका र अन्य कानुनी पाठ जस्ता कानुनी स्रोतहरूको व्यापक डाटाबेस समावेश गर्छ। यसले मोडेललाई सही र सान्दर्भिक उत्तरका लागि विशाल भण्डार उपलब्ध गराउँछ। Lawify को शक्ति यसको क्षेत्र-विशेष प्रशिक्षणमा छ, जसमा स्थानीय कानुनी शब्दावली, प्रक्रिया र सन्दर्भगत सूक्ष्मताहरूसँग व्यापक परिचय समावेश छ, जसले सही र सन्दर्भअनुकूल उत्तरको ग्यारेन्टी गर्छ।<br><br>",
