      "funding.text": "वयं संयुक्तराष्ट्रसङ्घस्य कार्यकारीविभागस्य सदस्येभ्यः मार्गदर्शनं प्राप्तवन्तः तथा Harvard MUN Impact Initiative-तः वित्तपोषणं प्राप्तवन्तः - सर्वाङ्गीणं तृतीयं पुरस्कारं ४०० USD मितं लब्ध्वा। अधिकवित्तपोषणाय Diana, Duke of Edinburgh इत्यादीनि प्रसिद्धपुरस्काराणि अपि आवेदयितुं वयं योजयामः। इदं वित्तपोषणम् अनिवार्यं यतः प्रतिरूपाय GPT4o-टोकन्स् आवश्यकानि, यानि १ मिलियन-टोकन्स्-कृते प्रायः २० USD मूल्यं भवन्ति। अस्माकं मञ्चस्य प्रचाराय World Foundation for Peace and Sustainability इत्यनेन सह सम्भाव्या भागीदारी अपि अस्ति।",
