      "contactsec.cta": "आतां मेल करात",
      "audience.title": "आमचे प्रेक्षक",
      "audience.text": "Lawify कसल्याच खास लोकसमूहाक लक्ष्य करिना; उलट, ब्हंवीं मनशां वेगवेगळ्या सामाजिक-आर्थिक पार्श्वभूमीतल्यान येतात आनी सगळ्यांक Lawify वापरून फायदो जावंक शकता हें आमी जाणात. शोषण जाल्ल्या कामगारांच्यो, छळ सोंशिल्ल्या नवरा-बायलेचो, वा विश्वासघात जाल्ल्या सहसंस्थापकांच्यो असह्य कहाण्यो फकत एका बटणाच्या क्लिकान आनी फुकट सोडोवपाचो आमचो हेत आसा.",
      "farmers.title": "शेतकारांखातीर",
      "farmers.text": "Lawify शेतकार आनी ग्रामीण समाजाच्या वांगडा उबो आसा, जमनीच्या मालकी कागदपत्रांक, कुळावार आनी वारसा हक्काच्या नोंदींक, आनी सरकारी पेन्शन आनी कल्याण योजनांक सोप्या भासेंत समजून घेवपाक तांकां मदत करता - जाका लागून कागदपत्रां समजपाक आतां वकिलाची वा शारांत वचपाची गरज उरना.",
      "convenience.title": "सुविधा हाडटा",
      "convenience.text": "Lawify वापरप खूब सोपें आसा - संवसारांतल्या कसल्याय भासेंत तुमचो प्रस्न इनपुट बॉक्सांत टायप करात (चॅटबॉट बऱ्याच आंतरराष्ट्रीय भासांनी निपुण आसा) आनी एंटर दाबात. प्रस्न कितलो तपशीलवार आसा ताचेर चॅटबॉट कांय सेकंदांनी जाप दितलो. Lawify राज्य, धर्म, वय आनी लिंग हांगासारिल्यो गजाली विचारांत घेता आनी फुडले प्रस्नांचीं जापांय दिवंक शकता.",
