      "whatyoushouldknow.heading": "Lawify लोकांच्या गरजेंतल्यान जल्माक आयला.",
      "effective.title": "प्रभावी वापर",
      "effective.text": "हें वापरप्याच्या देशाच्या न्यायकक्षेची म्हायती दिवपाखातीर तयार केलां, मागीर तें कायदेशीर सल्लो आसूं, पयल्या निवाड्यांचो शोध आसूं, वा कायदे आनी निवाड्यांचें संशोधन आसूं.<br><br>प्रॉम्प्ट जितलो नेमको आनी तपशीलवार, तितलें बरें Lawify वापरप्यांच्या गरजे प्रमाण आपलें जाप तयार करूंक शकता. सर्वसादारण प्रस्न विचारल्यार सर्वसादारण सल्लो मेळटलो, जो उलटो पडूंक शकता. Lawify फकत उपलब्ध पर्याय सांगतलें, वापरप्यांक मार्गदर्शन करचें ना वा एक निवडपाक सांगचें ना. हें न्यायालयांत वापरपाखातीर तयार केलां ना.",
      "quote.text": "“ही समस्या खरेंच ठळक आसा आनी ती सोडोवपाक जाय. कायद्याची म्हायती सगळ्यांत प्रभावी आनी कार्यक्षम तरेन, बऱ्या प्रशिक्षण मेळिल्ल्या AI कडल्यान सरळ तयार करून दिवपापरस चड बरी पद्दत कसली? हें सगळ्यांत बरें उपाय आसा.”",
      "quote.author": "Team Lawify",
      "ratio.eyebrow": "आश्चर्याची गजाल, प्रमाण आसा",
      "ratio.text": "संवसारांत सरासरी दर ३,५४७ लोकां फाटीं एक वकील आसा.",
      "eighty.text": "कमी उत्पन्नाचे लोक संवसारभर दिवाणी प्रकरणांखातीर वकील घेवपाचो खर्च करूंक शकनात, जें कायदेशीर मदतीच्या परवडपाच्या व्यापक समस्येची खूण दाखयता.",
      "ninetytwo.text": "Lawify ९२% आनी तातूंत चड अशा जबरदस्त अचूकतायेन काम करता.",
      "howitworks.eyebrow": "Lawify कशें काम करता?",
      "howitworks.text": "Lawify एक बऱ्या तरेन प्रशिक्षित LLM वापरता, जो हायपर-ट्यूनिंगा वरवीं खास करून कायदेशीर प्रस्नांखातीर सुधारला. वापरपी आपलो उश्टो प्रदेश निवडटात, जाका लागून त्या प्रदेशाच्या कायदेशीर चौकटीचेर आधारीत चॅट सत्र सुरू जाता. मागीर Lawify निवडिल्ल्या प्रदेशाशीं संबंदीत संविधान, आचारसंहिता, कायदे आनी अलीकडले दुरुस्ती हांचेसकट संबंदीत कायदेशीर कागदपत्रां लोड करता.<br><br>आमचो प्लॅटफॉर्म कायदेशीर साधनांचो एक सर्वसमावेशक डेटाबेस एकठांय करता, जसो कायदेशीर कायदे, न्यायालयीन निवाडे, नियामक मार्गदर्शक तत्त्वां आनी हेर कायदेशीर मजकूर. ताका लागून मॉडेलाक अचूक आनी संबंदीत जापां दिवपाखातीर व्हडलो साठो मेळटा. Lawify चें बळ ताच्या प्रदेश-विशिष्ट प्रशिक्षणांत आसा, जातूंत स्थानीक कायदेशीर संज्ञा, प्रक्रिया आनी संदर्भाच्यो बारकायो हांची सविस्तर वळख आसा, जाका लागून अचूक आनी संदर्भाक सुसंगत जापांची हमी मेळटा.<br><br>",
      "funding.eyebrow": "निधी",
      "funding.heading": "संवसारभरच्या उत्कृष्ट संस्थांचो आदार",
      "funding.text": "आमकां संयुक्त राष्ट्रांच्या कार्यकारी विभागांतल्या सभासदांकडल्यान मार्गदर्शन मेळ्ळें आनी Harvard MUN Impact Initiative कडल्यान निधी मेळ्ळो - एकंदर तिसरें पारितोषिक म्हणून ४०० USD मेळ्ळे. चड निधी खातीर Diana, Duke of Edinburgh अशा नामवंत पुरस्कारांखातीर अर्ज करपाची आमची येवजण आसा. हो निधी अत्यावश्यक आसा कारण मॉडेलाक GPT4o टोकन जाय, जांची किंमत १० लाख टोकनांक सुमार २० USD पडटा. आमच्या प्लॅटफॉर्माचो प्रचार करपाखातीर World Foundation for Peace and Sustainability कडेन संभाव्य भागीदारीय आसा.",
      "funding.cta": "आतां वापरात",
      "member.arhaan.bio": "एक मानाचो गणितज्ञ, लॉजिस्टिक्सांत निपुण आनी बास्केटबॉल खेळगो; शक्य थंय गणित आनी तर्क वापरपाक उत्सुक.",
      "role.cofounder": "सहसंस्थापक",
      "member.pranay.bio": "भारताचें कितल्यांदाच प्रतिनिधित्व केल्लो आंतरराष्ट्रीय वादपटू, आनी संगणक विज्ञान, तंत्रज्ञान वा व्यवस्थापन हांचे संबंधांत मान्यताप्राप्त तज्ञ.",
      "team.whoweare": "आमी कोण?",
      "team.heading1": "Team Lawify सादर करतात",
      "member.divyansh.bio": "आंतरराष्ट्रीय संबंदांचो विद्वान आनी फुटबॉल आनी व्हॉलीबॉल खेळपी उत्साही खेळगो. तो जागतिक घडामोडींकडेन संबंदीत संयुक्त राष्ट्रांत भवितव्याखातीर प्रयत्न करता.",
      "member.vatsal.bio": "व्यावसायिक उद्यमांत खूब कुशळ, मागीर जाहिरात, मार्केटिंग वा लॉजिस्टिक्स आसूं, संस्था चलोवपाशीं संबंदीत सगळ्या क्षेत्रांनी ताका अपार ज्ञान आसा.",
