      "whatwedo.eyebrow": "अस केह करने आं",
      "whatwedo.heading": "कानूनी जानकारी तकर पुज्जने दी कमी गी दिक्खियै, असेंगी कानूनी जानकारी दी इस असमानता गी दूर करने आस्ते कदम चुक्कने दी प्रेरणा मिली - इक इसी समस्या जेह्ड़ी समाज गी सच्चें असर पांदी ऐ।",
