      "contactsec.cta": "हुन मेल करो",
      "audience.title": "साडे यूज़र",
      "audience.text": "Lawify कुसै खास वर्ग गी निशाना नेईं बनांदा; इसदे उलट, अस Lawify च समझने आं जे बड़े सारे लोक अलग-अलग सामाजिक-आर्थिक पृष्ठभूमि थमां औंदे न ते सारे Lawify दा फायदा लेई सकदे न। अस शोषित मजदूरें, सताए गेदे जीवनसाथियें, एत्थूं तकर जे धोखा खाए दे सह-संस्थापकें दी असहनीय कहानियें गी हल करने दा मकसद रखने आं, सब किश इक बटन दबाने कन्नै ते मुफ्त।",
      "farmers.title": "किसानें आस्ते",
      "farmers.text": "Lawify किसानें ते ग्रामीण समुदायें दे कन्नै बी खड़ोता ऐ, उंदी जमीन दी मल्कियत दे कागजें, किरायेदारी ते विरासत दे रिकॉर्ड ते सरकारी पेंशन ते कल्याण योजनाएं गी सादी भाशा च समझने च मदद करदा ऐ - तां जे कागजात गी समझने आस्ते हून कुसै वकील जां शैहर दे चक्कर दी लोड़ नेईं रेहै।",
      "convenience.title": "सहूलत लेई औना",
      "convenience.text": "Lawify दा इस्तेमाल करना बड़ा सौखा ऐ: अपना सवाल दुनिया दी कुसै बी बोली च इनपुट बॉक्स च लिखो (चैटबॉट मते सारी अंतरराष्ट्रीय भाशाएं च माहिर ऐ) ते एंटर दबाओ। चैटबॉट फी सवाल कितना विस्तृत ऐ इस मताबक कुछ सकिंटें च जवाब देई देग। Lawify राज, धर्म, उमर ते लिंग आली गल्लें गी ध्यान च रखदा ऐ ते अग्गें दे सवालें दा जवाब बी देई सकदा ऐ।",
      "whatyoushouldknow.eyebrow": "तुसें गी केह पता होना चाहिदा",
      "whatyoushouldknow.heading": "Lawify लोकें दी लोड़ थमां पैदा होआ ऐ।",
      "effective.title": "असरदार इस्तेमाल",
      "effective.text": "इसी इस आस्ते बनाया गेदा ऐ जे यूज़र दे देश दे अधिकार-क्षेत्र दी जानकारी देई सकै, चाहे ओह कानूनी सलाह होऐ, पुराने फैसलें दी खोज होऐ, जां अधिनियमें ते मुकदमें दे कानूनें दी खोज होऐ।<br><br>प्रॉम्प्ट जित्ता ज्यादा सटीक ते बारीक होग, उत्ता ही बेहतर Lawify यूज़र दी लोड़ मताबक अपना जवाब ढाली सकग। आम सवाल पुच्छने कन्नै आम सलाह मिलग, जेह्ड़ी उल्टी पेई सकदी ऐ। Lawify सिर्फ उपलब्ध विकल्पें दी रूपरेखा दस्सग, यूज़र गी राह नेईं दिखाग जां उनेंगी कोई इक चुनने आस्ते नेईं आखग। इसी अदालत दे अंदर इस्तेमाल करने आस्ते नेईं बनाया गेदा ऐ।",
      "quote.text": "“ए समस्या सच्चें बड़ी साफ ऐ ते इसदा हल होना चाहिदा। कानून दी जानकारी गी सब थमां असरदार ते कुशल तरीके कन्नै देने थमां बेहतर होर केह तरीका होई सकदा ऐ, जेह्ड़ी इक खूब सिखलाई दित्ते गेदे AI थमां सीधी तैयार होऐ। ए सब थमां बेहतर हल ऐ।”",
      "quote.author": "टीम Lawify",
      "ratio.eyebrow": "हैरानी दी गल्ल ऐ जे अनुपात ऐ",
      "ratio.text": "दुनिया भर च औसतन हर 3,547 लोकें पिच्छे इक वकील ऐ।",
      "eighty.text": "कम आमदनी आले लोक दुनिया भर च दीवानी मामलें आस्ते वकील दा खर्चा नेईं चुक्की सकदे, ए कानूनी मदद दी महंगाई दी व्यापक समस्या गी साफ दस्सदा ऐ।",
      "ninetytwo.text": "Lawify 92% ते उसमें बी ज्यादा बेहतरीन सटीकता कन्नै कम्म करदा ऐ।",
      "howitworks.eyebrow": "Lawify किस चाल्ली कम्म करदा ऐ?",
      "howitworks.text": "Lawify इक बड़े खूब सिखलाई दित्ते गेदे LLM दा इस्तेमाल करदा ऐ, जिसी हाइपर-ट्यूनिंग दे जरिए खास करियै कानूनी सवालें आस्ते बेहतर बनाया गेदा ऐ। यूज़र अपना मनचाहा इलाका चुनदे न, जिसते उस इलाके दे कानूनी ढांचे उप्पर आधारित चैट सेशन शुरू होंदा ऐ। फी Lawify चुने दे इलाके कन्नै जुड़े दे संविधान, आचार संहिता, कानून ते हाल दे संशोधनें समेत ज़रूरी कानूनी दस्तावेज लोड करदा ऐ।<br><br>साडा प्लेटफॉर्म कानूनी स्रोतें दा इक व्यापक डेटाबेस जोड़दा ऐ, जि’यां कानूनी अधिनियम, अदालती फैसले, नियामक दिशानिर्देश ते होर कानूनी लेख। इसदे कन्नै मॉडल कोल सटीक ते ठीक जवाबें आस्ते बड़ा बडा भंडार रौंहदा ऐ। Lawify दी ताकत उसदी इलाके-विशेष सिखलाई च ऐ, जिस च स्थानीय कानूनी शब्दावली, प्रक्रियाएं ते संदर्भ दी बारीकियें कन्नै गैहरी पन्छान शामल ऐ, जेह्ड़ी सटीक ते संदर्भ दे मताबक सही जवाबें दी गारंटी देंदी ऐ।<br><br>",
      "funding.eyebrow": "फंडिंग",
