      "funding.cta": "हुन इस्तेमाल करो",
      "member.arhaan.bio": "इक सम्मानित गणितज्ञ, लॉजिस्टिक्स च माहिर ते बास्केटबॉल खिलाड़ी; जेह्ड़ा हर संभव हालात च गणित ते तर्क दा इस्तेमाल करने दी कोशश च ऐ।",
      "role.cofounder": "सह-संस्थापक",
