      "team.whoweare": "अस कौन आं?",
      "team.heading1": "टीम Lawify दा परिचय",
      "member.divyansh.bio": "अंतरराष्ट्रीय संबंधें दा विद्वान ते फुटबॉल ते वॉलीबॉल खेडने आला उत्साही खिलाड़ी। ओह संयुक्त राष्ट्र च, वैश्विक मामलें कन्नै जुड़ी दे भविक्ख आस्ते कोशश करा दा ऐ।",
      "member.vatsal.bio": "कारोबारी कम्में च बड़ा माहिर, चाहे विज्ञापन होऐ, मार्केटिंग होऐ जां लॉजिस्टिक्स, उसी कुसै बी संगठन गी चलाने कन्नै जुड़े दे सारे क्षेत्रें दी बड़ी जानकारी ऐ।",
