      "eighty.text": "کم آمدنی والین لوکن چھنہ استطاعت زِ تِہ پوری دنیاہس منز دیوانی معاملن خاطرہ وکیلک خرچہ برداشت کرن، یہ چھُ قانونی مدد ہنز مہنگائی ہند وسیع مسئلہ ظاہر کران۔",
      "ninetytwo.text": "Lawify چھُ 92% تہ تِتھہ زیادہ شاندار درستگی پیٹھ کم کران۔",
      "howitworks.eyebrow": "Lawify کتھ پیٹھ کم کران چھُ؟",
      "howitworks.text": "Lawify چھُ اکھ بوڈ تربیت یافتہ LLM استعمال کران، یمس ہائپر ٹیوننگ ذریعہ خاص کٔرِتھ قانونی سوالن خاطرہ بہتر بناونہ آمت چھُ۔ صارف چھہ پنُن مطلوب علاقہ چُنان، یُس تس علاقچ قانونی ڈھانچس پیٹھ مبنی چیٹ سیشن شروع کران چھُ۔ پتہ Lawify چھُ چُنِتھ علاقس متعلق آئین، ضابطہ اخلاق، قانون تہ تازہ ترمیمن سمیت ضروری قانونی دستاویز لوڈ کران۔<br><br>اسہِ ہند پلیٹ فارم چھُ قانونی ماخذن ہند جامع ڈیٹابیس شامل کران، یتھ منز قانونی ایکٹ، عدالتی فیصلہ، ریگولیٹری ہدایات تہ دیگر قانونی تحریرات شامل چھہ۔ یمہ سان چھُ ماڈلس صحیح تہ مناسب جوابن خاطرہ بوڈ ذخیرہ میلان۔ Lawifyچ طاقت چھ تُمنز علاقہ مخصوص تربیت منز، یتھ منز مقامی قانونی اصطلاحن، طریقہ کارن تہ سیاقی باریکین سان گوڑھ واقفیت شامل چھ، یُس صحیح تہ سیاق مطابق جوابن ہنز ضمانت چھُ دوان۔<br><br>",
      "funding.eyebrow": "فنڈنگ",
      "funding.heading": "پوری دنیاہچ بہترین اداره ہندِ حمایت",
      "funding.text": "اسہِ ہیوک اقوام متحدچ ایگزیکٹو شعبچ رکنن پیٹھ رہنمائی تہ حاصل کور ہارورڈ MUN امپیکٹ انیشیٹو پیٹھ فنڈنگ - یتھ منز اسہِ ہیوک مجموعی طور 400 USDچ تریم انعام۔ اسہِ چھہ ڈیانا، ڈیوک آف ایڈنبرا وغیرہ ہیو مشہور انعامن خاطرہ تہ درخواست دنچ منصوبہ بناوان، تاکہ مزید فنڈنگ میلہِ۔ یہ فنڈنگ چھ لازمی کینہہ ماڈلس چھہ GPT4o ٹوکنن ہنز ضرورت، یمن ہند قیمت چھہ 10 لاکھ ٹوکنن خاطرہ تقریباً 20 USD۔ اسہِ ہند چھُ عالمی امن تہ پائیداری فاؤنڈیشن سان تہ پلیٹ فارمک پرچار کرنہ خاطرہ ممکنہ شراکت داری۔",
      "funding.cta": "ہُنہ استعمال کرو",
      "member.arhaan.bio": "اکھ معزز ریاضی دان، لاجسٹکس منز ماہر تہ باسکٹ بال کھیلُن والین؛ یُس ہر ممکن حالتس منز ریاضی تہ منطق استعمال کرنچ کوشش کران چھُ۔",
      "role.cofounder": "شریک بانی",
