      "audience.title": "ᱟᱞᱮᱜ ᱥᱩᱱᱩᱜᱤᱭᱟᱹ",
      "audience.text": "Lawify ᱫᱚ ᱪᱮᱫᱟᱜ ᱵᱷᱤᱱ ᱥᱟᱢᱟᱡ ᱥᱮ ᱥᱟᱱᱟᱢ ᱥᱮᱞᱮᱫ ᱵᱟᱭ ᱛᱷᱟᱯᱚᱭᱟ; ᱚᱱᱟ ᱵᱚᱫᱚᱞ ᱨᱮ, Lawify ᱨᱮ ᱟᱞᱮ ᱵᱩᱡᱷᱟᱹᱣ ᱢᱮᱱᱟ ᱡᱤᱛ ᱦᱚᱲ ᱵᱷᱤᱱ ᱵᱷᱤᱱ ᱥᱟᱢᱟᱡ ᱟᱨ ᱟᱨᱛᱷᱤᱠ ᱥᱟᱱᱟᱢ ᱠᱷᱚᱱ ᱟᱹᱛᱩ ᱠᱟᱱᱟ ᱟᱨ ᱡᱚᱛᱚ ᱫᱚ Lawify ᱵᱮᱵᱷᱟᱨ ᱠᱷᱚᱱ ᱵᱷᱚᱞᱟ ᱧᱟᱢ ᱫᱟᱲᱮᱭᱟᱜ ᱠᱟᱱᱟ। ᱟᱞᱮ ᱠᱟᱹᱢᱤ ᱛᱮ ᱥᱟᱵᱟᱝ ᱥᱟᱵᱟᱝ ᱠᱟᱹᱢᱤᱭᱟᱹ ᱫᱚᱨᱚᱜ, ᱠᱷᱟᱹᱱᱜᱟᱹ ᱥᱟᱶ ᱥᱟᱵᱟᱝ ᱟᱹᱜᱩ ᱛᱮ ᱥᱟᱵᱟᱝ ᱧᱮᱞ ᱨᱮᱱᱟᱜ ᱥᱚᱨᱚᱥ ᱠᱷᱚᱱ ᱥᱮ ᱵᱷᱤ ᱥᱟᱵ ᱥᱟᱵ ᱠᱷᱚᱱ ᱥᱮ ᱠᱷᱟᱹᱱᱜᱟᱹ ᱵᱷᱟᱨᱥᱟ ᱵᱷᱟᱸᱜ ᱠᱟᱱᱟ - ᱡᱚᱛᱚ ᱢᱤᱫ ᱠᱞᱤᱠ ᱛᱮ ᱟᱨ ᱵᱷᱟᱲᱟ ᱵᱟᱝ ᱠᱷᱚᱨᱚᱪ ᱛᱮ ᱥᱟᱵ ᱫᱚᱨᱟᱜ ᱞᱟᱹᱜᱤᱫ ᱠᱟᱹᱢᱤ ᱞᱟᱹᱠᱛᱤᱭᱟᱹ।",
