      "voicechat.eyebrow": "टाइप खालामनाय सिगां राव",
      "voicechat.title": "भ'इस चेट",
      "voicechat.intro": "नोंथांनि आइन सोंनाय फोरोंनो जेंनाय सावरायनाय आरो Lawify नि फिननायफोरखौ नोंथांनो गोसो गोसो सुंनो हागोन। माइकआव राव, लिरफोरखौ गुबुन चेटआव कपि खालाम, आरो बट'नि फिननायखौ रिडारआव पेस्ट खालामनानै सुं।",
