      "voicechat.speak": "राव",
      "voicechat.stop": "थां",
      "voicechat.unsupported": "नोंथांनि ब्राउजारजों भ'इस रिकग्निसन समजिनाय गैया। स्पिच-टु-टेक्स्ट सुबिधानि थाखाय Chrome नाथाय Edge ब्यबहार खालाम।",
      "hero.eyebrow": "जोंनि मिसन",
